export function getStoryStrings(lang = 'ru') {
  if (lang === 'pt-br') lang = 'pt';
  if (lang === 'es-mx') lang = 'es';
  return STORY_TRANSLATIONS[lang] || STORY_TRANSLATIONS['ru'] || STORY_TRANSLATIONS['en'];
}
